AuctioneerLocalizations.frFR = {

		-- Section: Help
		["AAMU_Help_VendorOptions"]	= "AAMU : Options vendeur";
		["AAMU_Help_VendorOptionsAnswer"]	= "AutoMagic vendra automatiquement les objets achetés pour revente. Il pourra aussi vendre automatiquement les objets gris ou d'une liste d'objets personnalisable.";
		["AAMU_Help_WhatAutoMagic"]	= "Qu'est-ce qu'AutoMagic ?";
		["AAMU_Help_WhatAutoMagicAnswer"]	= "AutoMagic est un travail en cours. Son but est d'automatiser les tâches que rencontrent les traders qui peuvent être pénibles, et dans les limites fixées par Blizzard. \n\nAutoMagic actuellement  vendre n'importe quel objet acheté avec SearchUI pour les pnj marchands, n'importe quel objet \"gris\" (valeur la plus basse) ou n'importe quel objet dans la liste de vente automatique. Si AutoMagic est activé, quand vous ouvrez une fenêtre d'échange avec un pnj marchand, vous verrez une liste des objets à vendre.";
		["AAMU_Help_WhatMailGUI"]	= "Qu'est-ce que Mail GUI ?";
		["AAMU_Help_WhatMailGUIAnswer"]	= "Ceci affiche une fenêtre quand la boite aux lettres est ouverte, qui autorise l'auto-chargement des objets dans la boite d'expédition selon les raisons d'achat de SearchUI. Les réglages du module ItemSuggest  peuvent être utilisées à la place des réglages de SearchUI. Ceci est très pratique pour les envois de masse d'objets achetés pour une profession autre que celle que possède le personnage.";
		["ADV_Help_CannotDeleteProfile"]	= "Le profil choisi ne peut pas être supprimé";
		["ADV_Help_InvalidProfileName"]	= "Impossible de créer un nouveau profil : merci d'entrer d'abord le nom du nouveau profil";
		["ADV_Help_PostAuctionError"]	= "Ce poste ne peut être affichée à cause de l'erreur suivante: %s";
		["ADV_Help_UnresolvedAuctionsTolerance"]	= "Auctioneer est parfois incapable de résoudre un certain nombre de ventes aux enchères lors d'une analyse, causant ainsi un balayage incomplet. Unresolved Auctions Tolerance permet à Auctioneer de toujours marquer la numérisation comme complété si le nombre de ces erreurs est très faible. Peut être utile lorsque le serveur est instable, en particulier après les grosses mise à jour.";
		["ADV_Help_WhatAccuracy"]	= "Qu'est ce que l'erreur sur le Prix du Marché ?";
		["ADV_Help_WhatAccuracyAnswer"]	= "L'erreur sur de Prix du Marché vous autorise à définir le montant de l'erreur tolérée lorsque les prix du marché sont calculés. L'algorithme étant extrêmement complexe, seule une estimation peut être donnée. Baisser cette valeur donnera une estimation plus fiable, mais demandera plus de puissance de calcul (et peut être lent sur des vieux ordinateurs).";
		["ADV_Help_WhatClickHooks"]	= "Qu'est-ce que les crochets (Click-Hooks) ?";
		["ADV_Help_WhatClickHooksAnswer"]	= "Les crochets (Click-Hooks) vous permettent de faire une recherche sur un objet soit avec Alt-clique-droit sur l'objet dans vos sacs, ou Alt-clique un lien de l'objet dans la fenêtre de discussion.";
		["ADV_Help_WhatExactMatch"]	= "Qu'est-ce qu'une correspondance exacte ?";
		["ADV_Help_WhatExactMatchAnswer"]	= "Certains objets peuvent varier par leur suffixe (par exemple : de la chouette/de l'ours/de la Fouine), or leurs stats exactes (eg :  deux objets \"...de l'ours\", mais avec des stats différentes). Une correspondance exacte ne trouvera rien qui ne soit pas 100% identique.";
		["ADV_Help_WhatIsImage"]	= "Qu'est-ce qu'une image de l'hôtel des ventes ?";
		["ADV_Help_WhatIsImageAnswer"]	= "Quand vous analysez l'hôtel des Ventes, Auctioneer crée une image de ce qui est mis aux enchères. C'est ça l'image. Cela représente la meilleure approximation d'Auctioneer de ce qui est mis actuellement aux enchères. Si votre analyse est récente, ce sera raisonnablement juste, si l'analyse est datée, l'information ne sera pas pertinente.";
		["ADV_Help_WhatIsScanData"]	= "Qu'est-ce que l'infobulle des données scannées ?";
		["ADV_Help_WhatIsScanDataAnswer"]	= "La bulle d'aide des données scannées est une ligne qui apparait dans votre bulle d'aide vous informant le nombre de fois que l'objet a été vu à l'hôtel des ventes.";
		["ADV_Help_WhatPreferredChatFrame"]	= "Qu'est-ce que la fenêtre des sortie préféré ?";
		["ADV_Help_WhatPreferredChatFrameAnswer"]	= "La fenêtre de sortie préféré permet de choisir laquelle de vos fenêtres de discussion sera utilisé par Auctioneer pour écrire ses résultats. Choisir une fenêtre dans le menu déroulant et Auctioneer écrira ses sorties à venir dans cette fenêtre.";
		["ADV_Help_WhatPreferredLanguage"]	= "Qu'est-ce que la langue préférée ?";
		["ADV_Help_WhatPreferredLanguageAnswer"]	= "La langue préférée permet de choisir la traduction que vous voulez qu' Auctioneer utilise. Ceci peut être pratique si vous voulez qu'Auctionner utilise un langage différent du jeu lui-même. Nécessite un redémarrage ou /console reloadui.";
		["ADV_Help_WhatPriority"]	= "Qu'est-ce que la priorité de traitement ?";
		["ADV_Help_WhatPriorityAnswer"]	= "La Priorité de traitement définit la vitesse à laquelle traiter les données à la fin de l'analyse. Les valeurs les plus basses prennent plus de temps, mais vous permettront de bouger plus facilement. Des valeurs hautes réduisent le temps, mais peuvent causer des saccades. Les données mises à jour ne sont pas disponible avant la fin complète du traitement.";
		["ADV_Help_WhyForceLoad"]	= "Pourquoi forcer le chargement des données analysées ?";
		["ADV_Help_WhyForceLoadAnswer"]	= "Si vous voulez utiliser les données de l'Hotel des ventes dans le jeu, certaines personnes préfèrent avoir un temps de chargement du jeu plus long, plutôt que d'avoir un lag en jeu sur quelques secondes quand les données sont chargées à la demande.";
		["ADV_Help_WhyShowSummation"]	= "Qu'est-ce que le résumé après analyse (post scan) ?";
		["ADV_Help_WhyShowSummationAnswer"]	= "Ceci affiche le nombre d'enchères nouvelles, mises à jour, ou inchangées, et récoltées, par une analyse de l'hôtel des ventes.";
		["AHWC_Help_AuctionHouseScale"]	= "Échelle de la fenêtre de l'hôtel des ventes";
		["AHWC_Help_AuctionHouseScaleAnswer"]	= "Le curseur d'échelle de l'hôtel des ventes, ajuste la taille globale de la fenêtre de l'hôtel des ventes. La taille par défaut est 1.";
		["AHWC_Help_CompactUIFontScale"]	= "Taille de police de CompactUI";
		["AHWC_Help_CompactUIFontScaleAnswer"]	= "Le curseur de taille de police du CompactUI ajuste la taille du texte affiché dans les options de AucAdvance CompactUI. La taille par défaut est de 0.";
		["AHWC_Help_ProtectWindow"]	= "Que fait \"Protection de la fenêtre de l'HV\" ?";
		["AHWC_Help_ProtectWindowAnswer"]	= "La fenêtre de l'Hôtel des Ventes se ferme par défaut quand vous ouvrez d'autres fenêtres, telles que la fenêtre des talents, le journal des Quêtes ou la fenêtre de recherche de groupe. Cette option lui permet de rester ouverte, derrière ces autres fenêtres.";
		["AHWC_Help_RemberLastPosition"]	= "Se souvenir de la dernière position de la fenêtre";
		["AHWC_Help_RemberLastPositionAnswer"]	= "Si cette case est cochée, la fenêtre de l'hôtel des ventes se réouvrira au même endroit que sa dernière position connue.";
		["AHWC_Help_SearchUIScale"]	= "Échelle de SearchUI";
		["AHWC_Help_SearchUIScaleAnswer"]	= "Le curseur d'échelle de SearchUI ajuste la taille globale de SearchUI hors hôtel des ventes. La taille de défaut est de 1.";
		["AHWC_Help_whatisthis"]	= "Qu'est-ce que l'utilitaire de contrôle de la fenêtre de l'hôtel des ventes";
		["AHWC_Help_whatisthisAnswer"]	= "Cet utilitaire vous permet de faire glisser et de déplacer le cadre d'enchères pour cette session de jeu. Il vous suffit de cliquer et de le déplacer où vous le voulez. Il vous permet également de d'empêcher l'hôtel des ventes de se fermer lors de l'ouverture d'autres fenêtres de Blizzard.";
		["APPR_Help_BatchFollowingWouldPosted"]	= "Les objets suivants ont été automatiquement mis en vente :";
		["APPR_Help_BatchPostHelp1"]	= "La mise en vente groupée vous permet d'effectuer des actions automatiques sur tous les objets dans votre inventaire marqués \"traitement groupé\".";
		["APPR_Help_BatchPostHelp2"]	= "Vous devez maintenir enfoncées l'une des touches suivantes lorsque vous cliquez sur le bouton :";
		["APPR_Help_BatchPostHelp3"]	= "- Alt = Rafraichit automatiquement les objets en mise en vente groupée.";
		["APPR_Help_BatchPostHelp4"]	= "- Shift = Liste toutes les enchères qui pourraient être lancées, sans les lancer.";
		["APPR_Help_BatchPostHelp5"]	= "- RightClick = Met en ventes tous les objets groupés";
		["APPR_Help_BatchPostHelp6"]	= "- Alt + RightClick un point de basculer après Batch on / off";
		["APPR_Help_BatchUnknownKeyCombo"]	= "Combinaison de touches inconnue tout en cliquant sur le bouton \"mise en ventes groupée\".";
		["APPR_Help_CannotPostAuctions"]	= "Impossible de mettre ces objets en vente :";
		["APPR_Help_CouldNotPost"]	= "Impossible de poster l'élément";
		["APPR_Help_CouldNotQueue"]	= "Impossible de mettre l'élément dans la file";
		["APPR_Help_Duration"]	= "Durée : {{%d hours}}";
		["APPR_Help_HowBidPriceCalculated"]	= "Comment le prix de l'enchère est-il calculé ?";
		["APPR_Help_HowBidPriceCalculatedAnswer"]	= "A l'exception des objets à prix fixe, l'enchère de départ est calculée à partir du prix d'achat immédiat. Les options de calcul vous permettent de définir comment le prix est réduit, et les différentes options se cumulent. Ainsi, si vous décidez d'un pourcentage de remise et d'une déduction du prix de dépôt, la valeur finale sera : (%s Buyout %s-%s Markdown %s-%s Deposit %s).";
		["APPR_Help_HowMarkdownPctCalculated"]	= "Comment le pourcentage de baisse est-il calculé ?";
		["APPR_Help_HowMarkdownPctCalculatedAnswer"]	= "Le prix est calculée en multipliant la valeur calculée par le pourcentage qui est spécifié dans les options. On la soustrait alors aux charges (prix fixe et/ou le coût de dépôt si spécifié) pour produire le prix final.";
		["APPR_Help_NeedOnlyHavePosting"]	= "Il faut %d %s, vous n'en avez que %d, mis en vente %d";
		["APPR_Help_PostedItems"]	= "{{%d}} objets envoyés";
		["APPR_Help_PostingBatch"]	= "Envoi par groupe de : %s";
		["APPR_Help_PostingItems"]	= "Envoi de {{%d}} objets";
		["APPR_Help_PostingLots"]	= "Envoi de {{%d}} lots de {{%d}}";
		["APPR_Help_PretendedItems"]	= "Nécessite {{%d}} objets";
		["APPR_Help_PretendingPostStacks"]	= "Faire semblant de mettre en ventes {{%d}} piles de {{%d}} à {{%s}} min et au prix d'achat de {{%s}} par pile";
		["APPR_Help_QueuedUpItems"]	= "{{%d}} objets mis en attente";
		["APPR_Help_QueueingItems"]	= "Mise en attente de {{%d}} objets";
		["APPR_Help_QueueingLots"]	= "Mise en attente de {{%d}} lots de {{%d}}";
		["APPR_Help_SkippingInvalidBuyoutValue"]	= "%s non traité : prix d'achat invalide";
		["APPR_Help_SkippingInvalidDuration"]	= "%s non traité : durée invalide";
		["APPR_Help_SkippingInvalidNumberStacks"]	= "%s non traité : nombre de piles/objets invalide";
		["APPR_Help_SkippingNoAuctionableItem"]	= "%s non traité : pas d'objet en état dans l'inventaire. Une réparation est peut-être nécessaire";
		["APPR_Help_SkippingNoBidValue"]	= "%s non traité : valeur de l'enchère non définie";
		["APPR_Help_SkippingNoStackSize"]	= "%s non traité : taille de pile non définie";
		["APPR_Help_SkippingNotEnoughItems"]	= "%s non traité : pas suffisamment d'objets";
		["APPR_Help_SkippingStackLargerAvailable"]	= "%s non traité : taille de pile supérieure à la quantité disponible";
		["APPR_Help_StacksAreadyPosted"]	= "%d piles de %s déjà mises en ventes";
		["APPR_Help_TotalBuyoutValue"]	= "Valeur de rachat totale : %s";
		["APPR_Help_TotalMinbidValue"]	= "Valeur de l'offre minimale totale : %s";
		["APPR_Help_WhatAppraiser"]	= "Qu'est-ce que l'Evaluateur?";
		["APPR_Help_WhatAppraiserAnswer"]	= "Appraiser (l'évaluateur) est un outil vous permettant de vous occuper rapidement de vos enchères et de se souvenir des dernières informations que vous avez entrées. L'interface d'Appraiser  est rattachée à la fenêtre de l'Hôtel des Ventes comme un onglet supplémentaire en bas de la fenêtre. Quand vous choisissez cet onglet pour la première fois, tous les objets de votre inventaire pouvant être mis aux enchères seront affichés dans une liste à la gauche de votre fenêtre. Quand vous sélectionnez un objet, la fenêtre de contrôle de l'objet apparait au centre et les ventes aux enchères concernant cet objet en bas. La fenêtre de contrôle vous permet de spécifier le nombre d'objet par pile et le nombre de piles que vous souhaitez mettre en vente grâce aux deux curseurs.";
		["APPR_Help_WhatClickHooks"]	= "Qu'est ce que les crochets (click-hooks) ?";
		["APPR_Help_WhatClickHooksAnswer"]	= "Les crochets (click-hooks) vous permettent de sélectionner un objet avec Alt-click ou de mettre en vente un objet par Alt-Shift-click.";
		["APPR_Help_WhatDefaultPricing"]	= "A quoi sert le modèle de prix par défaut ?";
		["APPR_Help_WhatDefaultPricingAnswer"]	= "Quand l'évaluateur (Appraiser) calcule le prix de mise en vente d'un objet, il va soit utiliser un prix du marché, qui est une moyenne de plusieurs autres modèles de prix, ou un prix calculé par un module de statistiques particulier d'AuctioneerAdvanced. Vous pouvez sélectionner un modèle par défaut qui sera utilisé pour les items qui n'ont pas de modèle déjà défini.";
		["APPR_Help_WhatStartingBid"]	= "Qu'est ce que l'enchère de départ ?";
		["APPR_Help_WhatStartingBidAnswer"]	= "L'enchère de départ est l'enchère minimum. C'est le prix que le premier enchérisseur doit atteindre ou dépasser pour mettre une enchère. Les enchères suivantes augmentent à chaque fois à partir de l'enchère en cours.";
		["ASAL_Help_StatSales"]	= "Qu'est ce que les statistiques de vente?";
		["ASAL_Help_StatSalesAnswer"]	= "Les statistiques de vente sont des chiffres générés par le module de vente de la base de données de BeanCounter. Elles donnent la moyenne des prix pour tous les objets que vous avez vendus.";
		["ASKP_Help_WhatAskPrice"]	= "Qu'est ce que AskPrice  et que fait-il ?";
		["ASKP_Help_WhatAskPriceAnswer"]	= "AskPrice est un module qui permet à d'autres joueurs d'avoir la valeur d'objets par l'envoi de messages spéciaux dans différentes fenêtres de discussion, ou en vous envoyant ces messages directement, avec un chuchotement (/wisp).";
		["ASKP_Help_WhatTriggers"]	= "Quels sont ces déclencheurs, et comment sont-ils utilisés ?";
		["ASKP_Help_WhatTriggersAnswer"]	= "Les déclencheurs contrôlent comment quelqu'un vous demande un prix. \nLes mots clefs ajustables permettent à Auctioneer de répondre à des demandes en langage naturel, alors que les lettres déclenchantes permettent de demander pour des piles d'objets \n\nLes mots clefs par défaut répondent à \'what is [item link] worth?\' \nLes lettres déclenchantes par défaut répondent à \'? (stack size) [item link]\'";
		["BASC_Help_IgnoreOwnAuctionsAnswer"]	= "Cochant cette case permet de désactiver l'ajout de ventes aux enchères que vous avez posté vous à l'instantané.";
		["BASC_Help_WhatBasicFilter"]	= "Qu'est ce que le Filtre basic ?";
		["BASC_Help_WhatBasicFilterAnswer"]	= "Ce filtre vous permet de spécifier certains minimums pour un objet à inscrire dans la base de données, tels que le niveau de l'élément minimal, et la qualité minimale (Mauvais, Communs, Inhabituelles, rares, etc.). Il vous permet également de préciser de ne pas être enregistré certains éléments d'un vendeur. A utiliser si un vendeur postes tous ses articles au dessus ou en dessous du prix du marché. Vous pouvez même ignorer la totalité de ses articles.";
		["COMP_Help_HowToIgnore"]	= "Comment puis je ignorer les enchères d'un vendeur ?";
		["COMP_Help_HowToIgnoreAnswer"]	= "ALT click sur le vendeur que vous voulez ignorer, et choisir \"oui\" dans la fenêtre qui apparaitra. Le nom du vendeur sera marqué en rouge et placé dans la liste des ignorés du module FILTRE DE BASE.";
		["COMP_Help_HowToUnignore"]	= "Comment puis je ne plus ignorer les enchères d'un vendeur ?";
		["COMP_Help_HowToUnignoreAnswer"]	= "ALT click sur le vendeur que vous voulez cesser d'ignorer, et choisir \"oui\" dans la fenêtre qui apparaitra. Le nom du vendeur sera retiré de la liste des ignorés du module FILTRE DE BASE.";
		["COMP_Help_WhatBrowseOverride"]	= "Pourquoi vouloir empêcher d'autres modules de changer la fenêtre de navigation ?";
		["COMP_Help_WhatBrowseOverrideAnswer"]	= "Si vous avez un module tel que ScanProgress (Avancé de l'analyse) installé et activé, cela va changer votre interface utilisateur en rendant les objets que vous allez analyser non visible. Cette option va revenir à l'affichage où vous pourrez au contraire voir les objets que vous étes en train d'analyser.";
		["COMP_Help_WhatCollapse"]	= "Que fait enlever les valeurs monétaires les plus petites ?";
		["COMP_Help_WhatCollapseAnswer"]	= "Enlever les valeurs monétaires les plus petites retire les valeurs de l'ordre le plus petit quand elles sont nulles et cette omission ne change pas la précision de l'affichage du prix. \nCeci a pour effet de réduire la taille de l'affichage des prix, mais peut prêter à confusion avec des prix de longueur similaire qui sont d'un ordre différent (ie. 1pa 55pb ressemble à 1po 55pa) et si vous n'êtes pas attentif, vous pourriez dépenser plus que vous ne souhaitiez.";
		["COMP_Help_WhatCompactUI"]	= "Qu'est ce que CompactUI ?";
		["COMP_Help_WhatCompactUIAnswer"]	= "CompactUI est une interface où l'espace de navigation est optimisé pour remplacer l'interface de navigation par défaut de Blizzard. \nParce qu'elle modifie fortement vos cadres d'affichage des enchères, cette interface peut d'avérer être incompatible avec d'autres addons qui modifient aussi le cadre d'affichage des enchères. Dans ce cas, vous aurez à choisir entre CompactUI  et les autres addons. Vous pouvez désactiver CompactUI facilement en décochant la case \"autoriser l'usage\" de l'option CompactUI (nécessite un redémarrage) dans la fenêtre de réglage.";
		["COMP_Help_WhatPopup"]	= "Que fait autoriser l'aide par fenêtre surgissante (popup) ?";
		["COMP_Help_WhatPopupAnswer"]	= "Affiche une info-bulle par petite fenêtre surgissante (popup) à différents endroits de CompactUI.";
		["COMP_Help_WhatRequied"]	= "Qu'est ce que l'enchère demandée ?";
		["COMP_Help_WhatRequiedAnswer"]	= "L'interface standard de la bourse vous montre les enchères en cours. Dans le cas où l'enchère en cours n'est pas l'enchère de départ (ou enchère minimum), le montant actuel quand vous enchérissez sur cet objet sera l'enchère courante, ajoutée de l'incrément minimum. Donc, ce que vous payerez sera plus que ce qui est affiché dans la fenêtre quand vous n'êtes pas le premier enchérisseur. En cochant cette option, vous changez le comportement de CompactUI pour au contraire montrer l'enchère demandée que vous devrez faire, de façon à ce que, qu'il y ait déjà une enchère ou non, ce que vous verrez sera effectivement ce que vous allez payer.";
		["ILVL_Help_SlashHelp1"]	= "Aide pour Auctioneer Advance - iLevel";
		["ILVL_Help_SlashHelp2"]	= "cette aide de iLevel";
		["ILVL_Help_SlashHelp3"]	= "effacer la base de donnée des prix de iLevel %s courant";
		["ILVL_Help_SlashHelp5"]	= "Remise à zéro des statistiques iLevel pour";
		["ILVL_Help_WhatConfidence"]	= "Qu'est-ce que signifie l'intervalle de confiance?";
		["ILVL_Help_WhatConfidenceAnswer"]	= "La confiance est une valeur entre 0 et 1, plus c'est proche de 1 et meilleur la confiance est.";
		["ILVL_Help_WhatFiltered"]	= "Qu'entendez-vous par \"filtré\"?";
		["ILVL_Help_WhatFilteredAnswer"]	= "Les objets variant de plus de (1.5*valeur standard) sont ignorés et considérés comme ayant un prix mal fixé lors du calcul de déviation";
		["ILVL_Help_WhatIlevelStats"]	= "Que sont les stats iLevel?";
		["ILVL_Help_WhatIlevelStatsAnswer"]	= "Les stats iLevel sont des nombres générés par le module iLevel qui consiste en un écart-type filtré du prix d'un objet.";
		["ILVL_Help_WhatNormalized"]	= "Qu'est ce qu'un calcul Normalisé ?";
		["ILVL_Help_WhatNormalizedAnswer"]	= "Encore une fois en résumé, c'est la moyenne des valeurs déterminées dans le calcul de la variance de l'écart type.";
		["ILVL_Help_WhatStdDev"]	= "Qu'est-ce qu'un calcul d'Ecart Type ?";
		["ILVL_Help_WhatStdDevAnswer"]	= "Pour faire court, c'est le calcul de distance à la moyenne.";
		["ILVL_Help_WhyStackSize"]	= "A quoi sert l'option de multiplication par taille de lot?";
		["ILVL_Help_WhyStackSizeAnswer"]	= "Le Stat-ilevel original multipliait par la taille de lot d'un objet, mais certains préfèrent vendre les objets 1 par 1.";
		["OUTL_Help_RemoveOldOutliers"]	= "Est que cela peut enlever les données extrêmes (outliers) obsolètes ?";
		["OUTL_Help_RemoveOldOutliersAnswer"]	= "La réponses simple est non, cela fonctionne uniquement à partir de cette version. Tout paramètre que vous appliquez le sera à partir de maintenant, et les stats présentes sont laissées telles quelles.\nLa réponse compliquée? Alors vous voyez, il y a cette bouteille de lait...";
		["OUTL_Help_WhatOutlierFilter"]	= "Qu'est ce qu'un Filtre de Données Extrêmes (Outlier) ?";
		["OUTL_Help_WhatOutlierFilterAnswer"]	= "Lorsque vous enchérissez, certaines enchères peuvent être \"toxiques\", c'est à dire d'un prix bien des fois supérieur à la \"valeur réelle\" de l'objet.¶\nCe filtre détecte de telles données extrêmes et empêche leur entrée dans le flux de données si leur valeur excède un pourcentage fixé de la valeur normale de l'objet. Dans le même temps il autorise quand même des variations normales dans les prix des objets au jour le jour.";
		["PURC_Help_DayAverage"]	= "Alors on ne sauvegarde pas les enchères jour après jour?";
		["PURC_Help_DayAverageAnswer"]	= "Non, non-seulement cela prendrait de la place, mais demanderait de lourds chiffrages à chaque scan de l'hôtel des ventes.";
		["PURC_Help_HowMovingAverage"]	= "Comment sont calculées les moyennes mobiles par jour exactement ?";
		["PURC_Help_HowMovingAverageAnswer"]	= "La moyenne mobile par jour est ((X-1)*MoyenneMobileHier + MoyenneDujour) / X, où X est le nombre de jours (3,7, ou 14).";
		["PURC_Help_MultiplyStack"]	= "A quoi sert l'option de multiplication par taille de pile ?";
		["PURC_Help_MultiplyStackAnswer"]	= "Le Stat-Purchased original multipliait par la taille de la pile d'un objet, mais certains préfèrent vendre les objets 1 par 1.";
		["PURC_Help_SaferPrices"]	= "Comment sont calculés les prix \"fiables\" ?";
		["PURC_Help_SaferPricesAnswer"]	= "Tout ce qui a été vu plus de 100 fois et vendu à raison de 10 objets par jour (en moyenne), nous utilisons simplement la moyenne sur trois jours. \n\nDans les autres cas, nous évaluons la moyenne à 7 jours à 50%, et les moyennes à 3 et 14 jours entre 0-50% et 50-0% respectivement, selon le nombre de fois où l'objet a été vu par jour (entre 1 et 7).";
		["PURC_Help_SlashHelp1"]	= "Aide pour Auctioneer Advanced - Acheté";
		["PURC_Help_SlashHelp2"]	= "cette aide pour Acheté";
		["PURC_Help_SlashHelp3"]	= "effacer la base de données des prix Achetés {{%s}} actuels";
		["PURC_Help_SlashHelp4"]	= "Forcer la base de données des prix Achetés {{%s}} de l'archive (commencement d'une nouvelle journée)";
		["PURC_Help_SlashHelp5"]	= "Archiver {{%s}} statistiques journalières et commencer un jour nouveau";
		["PURC_Help_WhatMovingAverage"]	= "Que signifie 'moyenne mobile' ?";
		["PURC_Help_WhatMovingAverageAnswer"]	= "Moyenne mobile signifie qu'il mets plus de valeurs sur la moyenne mobile d'hier que sur la moyenne d'aujourd'hui. Le montant calculé est utilisé pour le calcul de la moyenne mobile de demain.";
		["PURC_Help_WhatPurchasedStats"]	= "Qu'est ce que les stats d'achat ?";
		["PURC_Help_WhatPurchasedStatsAnswer"]	= "Les stats d'achat dont les valeurs générées par le module 'Purchased', ce  module essaye de déterminer si un achat a été fait en direct (buy out) ou sur une enchère (bid). Il calcule aussi la moyenne mobile (3/7/14).";
		["SBTN_Help_WhatScanButton"]	= "Qu'est ce que les boutons d'analyse (scan) ?";
		["SBTN_Help_WhatScanButtonAnswer"]	= "Les boutons d'analyse (scan) sont les boutons Stop/Play/Pause/AvanceRapide dans la barre de titre du panneau de l'hôtel des Ventes.";
		["SDEV_Help_Confidence"]	= "Que signifie intervalle de confiance ?";
		["SDEV_Help_ConfidenceAnswer"]	= "L'intervalle de confiance est une valeur entre 0 et 1 qui détermine la force des calculs (le plus haut est le meilleur)";
		["SDEV_Help_Filtered"]	= "Que voulez-vous dire par filtré ?";
		["SDEV_Help_FilteredAnswer"]	= "Les objets en dehors de la variance (1,5 x Standard) sont ignorées et supposées être mal évalués quand on calcule la déviation.";
		["SDEV_Help_Normalized"]	= "Qu'est-ce qu'un calcul normalisé ?";
		["SDEV_Help_NormalizedAnswer"]	= "En résume, c'est la moyenne des valeurs déterminées dans le calcul de la variance d'écart type.";
		["SDEV_Help_SlashHelp1"]	= "Aide pour Auctioneer Avancé - Ecart type (StdDev)";
		["SDEV_Help_SlashHelp2"]	= "cet aide de l'Ecart type (StdDev)";
		["SDEV_Help_SlashHelp3"]	= "efface la base de donnée StdDev des prix actuels de %s";
		["SDEV_Help_SlashHelp4"]	= "Efface les stats StdDev pour";
		["SDEV_Help_StandardDeviationCalculation"]	= "Qu'est ce que le calcul d'Ecart Type ?";
		["SDEV_Help_StandardDeviationCalculationAnswer"]	= "En résumé, c'est le calcul de la distance à la moyenne.";
		["SDEV_Help_StdDevStats"]	= "Qu'est ce que les stats StdDev ?";
		["SDEV_Help_StdDevStatsAnswer"]	= "Les stats StdDev sont les nombres générés par le module StdDev consistant en un calcul d'écart type filtré du cout de l'objet.";
		["SDEV_Help_WhyMultiplyStack"]	= "Pourquoi avez la possibilité de multiplier par la taille de la pile?";
		["SDEV_Help_WhyMultiplyStackAnswer"]	= "Les statistiques StdDev  multipliées par la taille de la pile de l'objet, mais certaines personnes préfèrent traiter les objets à l'unité.";
		["SHTG_Help_SlashHelp1"]	= "Aide d'Auctioneer Advanced - Histogramme";
		["SHTG_Help_SlashHelp2"]	= "cet aide sur l'histogramme";
		["SHTG_Help_SlashHelp3"]	= "efface la base de données de l'histogramme des prix actuels de %s";
		["SHTG_Help_SlashHelp5"]	= "Effacer l'histogramme des statistiques pour";
		["SHTG_Help_WhatAdvantageHistogram"]	= "Quels avantages y a-t-il avec l'histogramme ?";
		["SHTG_Help_WhatAdvantageHistogramAnswer"]	= "L'histogramme des statistiques n'a pas de limite sur combien ou jusqu'à quand garder les données, donc peut garder aussi la trace d'objets à volume de vente important.";
		["SHTG_Help_WhatDisadvantagesHistogram"]	= "Quels désavantages y a-t-il avec l'histogramme ?";
		["SHTG_Help_WhatDisadvantagesHistogramAnswer"]	= "L'histogramme arrondie les prix légèrement pour aider à les stocker, il y a donc une légère perte de précision. Il est néanmoins précis au 1/250ème du prix du marché (un objet avec un prix sur le marché de 250 po aura son prix stocké au plus proche 1 po).";
		["SHTG_Help_WhatHistogramStats"]	= "Quel est l'histogramme des statistiques ?";
		["SHTG_Help_WhatHistogramStatsAnswer"]	= "L'histogramme des statistiques enregistre un histogramme des prix antérieurs.";
		["SHTG_Help_WhatIQR"]	= "Qu'est-ce que l'intervalle interquartile (IQR) ?";
		["SHTG_Help_WhatIQRAnswer"]	= "L'intervalle interquartile ou IQR est une mesure de dispersion. La moitié centrale des prix est située dans l'étendue de IQR. Un objet avec une moyenne de 100 po, et un IQR de 10 po, a des données consistantes. Si l'IQR était 100 po, les prix seraient un peu n'importe où.";
		["SHTG_Help_WhatMedian"]	= "Qu'est-ce que la médiane ?";
		["SHTG_Help_WhatMedianAnswer"]	= "La valeur médiane est la valeur pour laquelle la moitié des prix est supérieure et l'autre moitié inférieure.";
		["SIMP_Help_AverageMinimumBuyout"]	= "Quel intérêt à un prix moyen d'achat direct minimum ?";
		["SIMP_Help_AverageMinimumBuyoutAnswer"]	= "De cette façon, vous connaissez la santé du marché. Si le MBO (achat direct minimum) est plus grand que le MBO moyen, il est temps de vendre, et si le MBO moyen est plus grand que le MBO, c'est le moment d'acheter.";
		["SIMP_Help_HowAveragesCalculated"]	= "Comment la moyenne mobile journalière est-elle calculée, exactement ?";
		["SIMP_Help_HowAveragesCalculatedAnswer"]	= "La moyenne mobile journalière est ((X-1)*MoyenneMobileHier + MoyenneJournalière) / X, où X est le nombre de jours (3,7, ou 14).";
		["SIMP_Help_MinimumBuyout"]	= "Pourquoi dois-je connaitre le prix minimum de vente ?";
		["SIMP_Help_MinimumBuyoutAnswer"]	= "Alors que certains objets se vendront très bien en deux jours, d'autres ne partiront que si ils sont au prix le plus bas. C'est un calcul facile à faire, donc il a été incorporé dans ce module.";
		["SIMP_Help_MinimumBuyoutVariance"]	= "A quoi sert la 'variance de 10%' mentionnée plus haut ?";
		["SIMP_Help_MinimumBuyoutVarianceAnswer"]	= "Si le MBO actuel est compris dans un intervalle de 10% autour de la moyenne mobile, le MBO actuel sera seulement moyenné à un taux de 12,5%.";
		["SIMP_Help_MovingAverage"]	= "Que signifie \"moyenne mobile par jour\" ?";
		["SIMP_Help_MovingAverageAnswer"]	= "Moyenne mobile signifie qu'il y a plus de poids placé sur la moyenne mobile d'hier que sur la moyenne d'aujourd'hui. La valeur calculée est alors utilisée pour le calcul de la moyenne mobile de demain.";
		["SIMP_Help_NoDaySaved"]	= "Donc, pas de sauvegarde de la moyenne jour après jour ?";
		["SIMP_Help_NoDaySavedAnswer"]	= "Non, cela ne fait pas que prendre de la place, mais génère des calculs lourds à chaque analyse de l'hôtel des ventes, et ce n'est qu'un simple modèle simple.";
		["SIMP_Help_SimpleStats"]	= "Que sont les statistiques standards ?";
		["SIMP_Help_SimpleStatsAnswer"]	= "Les statistiques standards sont les nombres générés par le module Standard, ce module fait la moyenne de tout les prix des objets qu'il voit et produit une moyenne mobile dur 3. 7 et 14 jours. Il donne aussi un achat direct minimum journalier (MBO) ainsi qu'une moyenne mobile des achats directs minimum avec une variance de 10%.";
		["SIMP_Help_SlashHelp1"]	= "Aide pour Auctioneer Avancé - Standard";
		["SIMP_Help_SlashHelp2"]	= "cette aide de Standard";
		["SIMP_Help_SlashHelp3"]	= "efface la base de données de prix Simple de %s";
		["SIMP_Help_SlashHelp4"]	= "oblige les stats journalières de %s Standard à être archivées (débuter un nouveau jour)";
		["SIMP_Help_SlashHelp6"]	= "Archivage des statistiques journalières de {{%s}} et début d'une nouvelle journée";
		["SIMP_Help_SlashHelpClearingData"]	= "%s - Simple: effacer les données pour %s pour {{%s}}";
		["SIMP_Help_WhyMultiplyStack"]	= "Pourquoi avoir l'option de multiplier la taille des piles ?";
		["SIMP_Help_WhyMultiplyStackAnswer"]	= "Stat-Standard d'origine multiplié par la taille de la pile d'objets, mais certains préfèreront avoir à faire à une valeur par objet unique.";
		["SIMP_Help_WhyVariance"]	= "Variance du prix d'achat immédiat";
		["SIMP_Help_WhyVarianceAnswer"]	= "Parce que beaucoup de gens vendent leurs objets à des prix ridicules (trop bas ou trop haut), ce module sert à empêcher ces prix d'affecter la moyenne.";
		["SPRG_Help_WhatScanProgress"]	= "Qu'est-ce l'indicateur de progression de l'analyse (scan) ?";
		["SPRG_Help_WhatScanProgressAnswer"]	= "L'indicateur \"Analyse (scan) en Cours\" est le texte qui apparait pendant que vous analysez l'hôtel des Ventes. Il affiche : la vitesse de l'analyse, les enchères actuelles et le nombre total de enchères analysées, ainsi que le nombre de pages actuel et le total des pages analysées.";
		["UCUT_Help_WhatUndercut"]	= "Qu'est-ce que le module Concurrence ?";
		["UCUT_Help_WhatUndercutAnswer"]	= "Le module Concurrence vous permet de vous placer sous le plus bas prix de chaque objet disponible, suivant vos réglages.\n\nIl est recommandé de n'activer Concurrence qu'après les autres modules.";

